/* SPRITE_ANIM v0.1 (design specs/SPRITE_ANIM.md, D2070-D2089; red, held for Vincent): battle sprites take a pose frame.
   Each form keeps today's sprite as frame 0 ('base') and adds five frames, all in its stage's own letters and PAL:
     breathe (idle, the upper body settles 1 px), windup (leans back, eyes set), strike (leans in), hit (a flinch: ducks,
     leans away, eyes squeezed shut; never hurt), happy (eyes close upward when befriended).
   A frame is { half } (8 columns, mirrored like a stage), { full } (16 columns of the stage's letters, not mirrored: the
   leans) or { grid } (16 columns of PAL keys, for a grid stage). Rows are made by tools/gen_sprite_anim.js; by:'hand' rows
   were tuned by hand and the tool keeps them. Nothing here touches the save.
   saPose() picks the frame from the battle's own clocks: the idle clock, B.punch (the go/windup/contact/stop/knock steps),
   B.fx lunge and hearts, B.calm. FULL: every frame. CALM (and reduced motion): today's idle (bob and blink) plus the strike,
   hit and happy frames held still; no breathe, no wind-up. OFF: today's sprite, bob and blink exactly. The flash clock,
   lunge, squash, knock and shake are untouched: the frame is drawn inside them. */
'use strict';
const SA = {
  on: true,                       // false draws today's battle sprites in every mode (a way back, and the tests' baseline)
  idleMs: 500,                    // FULL: base 500 ms, breathe 500 ms
  blinkEvery: 2600, blinkMs: 130, // today's blink, kept in every mode
  foeLag: 250, foeBlinkLag: 1170, // FULL: the foe breathes and blinks out of step with the partner
  windupMs: 80,                   // MV_PUNCH.common.anticip_ms[1]: the pull-back
  hitMinMs: 170,                  // MV_PUNCH.common.blink_state_min_ms: a hit frame never shows for less
  frames: ['breathe', 'windup', 'strike', 'hit', 'happy'],
  fade: null,                     // set by game.js: { col: fadedCol, key: FADE_KEY } (CREATURES_SLICE §5 faded state)
};

// The pose for one battler this frame. who: 'me' | 'foe' | 'foe2' | 'ally'. ft: the battle's fx clock (fxT), t: now.
// Returns { f, blink, bob }: f a frame name ('base' is today's sprite), blink true for today's blink sprite, bob 0/1 px.
function saPose(mode, who, ft, t, B) {
  const today = { f: 'base', blink: (ft % SA.blinkEvery) < SA.blinkMs, bob: Math.floor(ft / 450) % 2 };
  if (!SA.on || mode === 'off' || mode === 'calm' && !B) return today;
  const side = who === 'me' || who === 'foe' ? who : null;
  if (mode === 'calm') {
    if (side && B.fx) for (let i = 0; i < B.fx.length; i++) {
      const e = B.fx[i];
      if (e.who === side && e.kind === 'lunge' && ft - e.t0 >= 0 && ft - e.t0 < e.dur) return { f: 'strike', blink: false, bob: today.bob };
    }
    if (side && B.calm && B.calm.who === side) { const a = t - B.calm.t0; if (a >= 0 && a < Math.max(SA.hitMinMs, B.calm.ms)) return { f: 'hit', blink: false, bob: today.bob }; }
    if (side && saHearts(B, side, ft)) return { f: 'happy', blink: false, bob: today.bob };
    return today;
  }
  if (side && B && B.punch && B.punch.mode === 'full' && !B.ff && typeof MV_PUNCH !== 'undefined') {
    const P = B.punch, ms = t - P.t0, C = MV_PUNCH.common.contact_ms;
    const stop = typeof mvScaled === 'function' ? mvScaled(P.type, P.variant).stop : 60;
    if (P.who === side && ms >= 0) {
      if (ms < SA.windupMs) return { f: 'windup', blink: false, bob: 0 };
      if (ms < C + stop) return { f: 'strike', blink: false, bob: 0 };
    }
    if (P.who !== side && ms >= C) {
      const kn = typeof mvPunchType === 'function' ? mvPunchType(P.type).knock : { out: 60, back: 160 };
      if (ms - C < Math.max(SA.hitMinMs, stop + kn.out + kn.back)) return { f: 'hit', blink: false, bob: 0 };
    }
  }
  if (side && B && saHearts(B, side, ft)) return { f: 'happy', blink: false, bob: 0 };
  const lag = who === 'me' || who === 'ally' ? 0 : 1;
  const breathe = Math.floor((ft + lag * SA.foeLag) / SA.idleMs) % 2 === 1;
  const blink = ((ft + lag * SA.foeBlinkLag) % SA.blinkEvery) < SA.blinkMs;
  return { f: breathe ? 'breathe' : 'base', blink: blink, bob: 0 };
}
function saHearts(B, who, ft) {
  if (!B.fx) return false;
  for (let i = 0; i < B.fx.length; i++) { const e = B.fx[i]; if (e.who === who && e.kind === 'hearts' && ft - e.t0 >= 0 && ft - e.t0 < e.dur) return true; }
  return false;
}

// Letter rows (16 wide) to PAL-key rows, the way buildSprite paints a half: e -> k, i -> w, a letter -> its col colour.
// blink: an eye pixel with an eye below takes col.a, the lowest eye row k (buildSprite's blink rule).
let SA_KEY = null;
function saKeys(rows, col, blink) {
  if (!SA_KEY) { SA_KEY = {}; for (const k in PAL) if (!SA_KEY[PAL[k]]) SA_KEY[PAL[k]] = k; }
  const key = (v) => SA_KEY[v] || 'm', eye = (c) => c === 'e' || c === 'i';
  return rows.map((r, y) => r.split('').map((ch, x) => {
    if (ch === '.') return '.';
    if (eye(ch)) {
      if (blink) return (y < 15 && eye(rows[y + 1][x])) ? key(col.a) : 'k';
      return ch === 'e' ? 'k' : 'w';
    }
    return key(col[ch] || PAL.m);
  }).join(''));
}
// The n (normal), b (blink) and w (white) sprites of one frame, 18x18 like SPR. null if the form has no such frame.
const SA_CACHE = {};
function saSet(si, stage, faded, f) {
  const sp = SPECIES[si], st = sp && sp.stages[stage | 0], row = sp && SPRITE_ANIM[sp.id + '/' + (stage | 0)], fr = row && row[f];
  if (!st || !fr) return null;
  const k = si + '/' + (stage | 0) + '/' + (faded ? 1 : 0) + '/' + f;
  if (SA_CACHE[k]) return SA_CACHE[k];
  let col = st.col || null;
  if (faded && col && SA.fade) col = SA.fade.col(col);
  let set;
  if (fr.half) set = { n: buildSprite(fr.half, col, 'normal'), b: buildSprite(fr.half, col, 'blink'), w: buildSprite(fr.half, col, PAL.w) };
  else if (fr.full) {
    const n = saKeys(fr.full, col, false), b = saKeys(fr.full, col, true);
    set = { n: buildSprite(n, null, 'normal'), b: buildSprite(b, null, 'normal'), w: buildSprite(n, null, PAL.w) };
  } else {
    const g = faded && SA.fade ? fr.grid.map((r) => r.split('').map((c) => (c === '.' ? '.' : SA.fade.key[c] || c)).join('')) : fr.grid;
    const n = buildSprite(g, null, 'normal');
    set = { n: n, b: n, w: buildSprite(g, null, PAL.w) };
  }
  return (SA_CACHE[k] = set);
}

